// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import { canvasGraph } from '../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { routeDrawnEdges, routeDrawnGraph } from '../../../main/frontend/graph-explorer/graph-edge-routing.ts';
import { curveMidpoint, nearestEdge } from '../../../main/frontend/graph-explorer/edge-hit.ts';
import { createGraphVertexCache } from '../../../main/frontend/graph-explorer/graph-webgl.ts';
import { computeEdgePorts, curveSamples, distributeCircularPortParameters, edgeGeometry, edgePortKey, graphNodeSize, nodeBoundaryPoint, optimizeEdgeBends, quadraticPoint, segmentDistance } from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import { computeGraphLayout } from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import { STATEMENT_LINK_EDGE_PREFIX } from '../../../main/frontend/graph-explorer/statement-links.ts';
import { badExportGraph, iri } from './fixtures/layout-demo-graph.mjs';

const curveOf = (graph, bends, edgeId) => {
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(graph.nodes, graph.edges);
  const edge = graph.edges.find((candidate) => candidate.id === edgeId);
  return edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edgeId) ?? 0,
    ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)));
};

test('hidden values and classes never bend the drawn arrows', () => {
  // Hidden literals and classes sit exactly where the sane detours of Acme→Oslo and Acme→Widget would pass.
  const hidden = (name, kind) => kind === 'literal'
    ? { x: 260 + ((name.length * 37) % 400), y: 300 + ((name.length * 13) % 60) }
    : { x: 100 + ((name.length * 53) % 700), y: 330 };
  const graph = badExportGraph(hidden);
  const drawn = canvasGraph(graph, false);
  assert.equal(drawn.nodes.length, 10);
  const routed = routeDrawnGraph(graph, false), alone = routeDrawnGraph(drawn, false);
  assert.deepEqual([...routed.bends].sort(), [...alone.bends].sort(), 'hidden cards changed the lanes');
  assert.deepEqual([...routed.routes].sort(), [...alone.routes].sort(), 'hidden cards changed the routes');
  // Acme→Oslo runs along a row with Gizmo between them: the arrow detours, through the empty row below rather than the
  // narrow gap under Carol, and is barely longer than the straight line.
  const acmeOslo = `${iri('Acme')}|${iri('locatedIn')}|${iri('Oslo')}`;
  const byId = new Map(drawn.nodes.map((node) => [node.id, node]));
  const acme = byId.get(iri('Acme')), oslo = byId.get(iri('Oslo'));
  const route = routed.routes.get(acmeOslo);
  assert.ok(route && route.points.length > 2, 'Acme→Oslo is routed round Gizmo');
  assert.ok(route.points.slice(1, -1).every((p) => p.y > Math.max(acme.y, oslo.y)), 'the detour must use the empty row below, not pass under Carol');
  const length = route.points.reduce((sum, p, i) => (i ? sum + Math.hypot(p.x - route.points[i - 1].x, p.y - route.points[i - 1].y) : 0), 0);
  assert.ok(length <= Math.hypot(oslo.x - acme.x, oslo.y - acme.y) * 1.3, `Acme→Oslo detour ${length.toFixed(0)} px`);
  for (const node of drawn.nodes) {
    if (node.id === acme.id || node.id === oslo.id) continue;
    const size = graphNodeSize(node);
    assert.ok(!route.points.some((p, i) => i && segmentMeetsCard(route.points[i - 1], p, node, size)), `the detour crosses ${node.label}`);
  }
  assert.equal(routeDrawnEdges(graph, true).size, 27, 'with Values on every edge is routed');
});

/** Whether segment a–b meets a card (Liang–Barsky). */
function segmentMeetsCard(a, b, node, size) {
  let lo = 0, hi = 1;
  for (const [axis, half] of [['x', size.width / 2], ['y', size.height / 2]]) {
    const delta = b[axis] - a[axis], min = node[axis] - half, max = node[axis] + half;
    if (Math.abs(delta) < 1e-12) { if (a[axis] < min || a[axis] > max) return false; continue; }
    const t0 = (min - a[axis]) / delta, t1 = (max - a[axis]) / delta;
    lo = Math.max(lo, Math.min(t0, t1)); hi = Math.min(hi, Math.max(t0, t1));
    if (hi < lo) return false;
  }
  return true;
}

test('layout routing ignores the statement-link springs the app adds for reifiers', async () => {
  const node = (id, x, y) => ({ id, label: id, kind: 'iri', x, y });
  const graph = { revision: 1, nodes: [node('s', 0, 0), node('o', 300, 0), node('r', 150, 200)], edges: [
    { id: 'e', source: 's', target: 'o', predicate: 'urn:p', label: 'p' },
    { id: `${STATEMENT_LINK_EDGE_PREFIX}x:s`, source: 'r', target: 's', predicate: 'urn:reifies', label: 'reifies' },
    { id: `${STATEMENT_LINK_EDGE_PREFIX}x:o`, source: 'r', target: 'o', predicate: 'urn:reifies', label: 'reifies' },
  ] };
  const result = await computeGraphLayout(graph, { mode: 'network' });
  assert.deepEqual([...result.bends.keys()], ['e']);
  assert.equal(result.positions.size, 3);
});

const card = (id, x, y) => ({ id, label: id, kind: 'iri', x, y });
const link = (source, target) => ({ id: `${source}-${target}`, source, target, predicate: 'urn:p', label: 'p' });
function obstructedCards(graph, bends) {
  const byId = new Map(graph.nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(graph.nodes, graph.edges);
  const hits = [];
  for (const edge of graph.edges) {
    const curve = edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edge.id) ?? 0,
      ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)));
    for (const node of graph.nodes) {
      if (node.id === edge.source || node.id === edge.target) continue;
      const size = graphNodeSize(node);
      for (let i = 0; i <= 2000; i++) {
        const p = quadraticPoint(curve.start, curve.control, curve.end, i / 2000);
        if (Math.abs(p.x - node.x) < size.width / 2 + 2 && Math.abs(p.y - node.y) < size.height / 2 + 2) { hits.push(node.id); break; }
      }
    }
  }
  return hits;
}

test('a detour blocked by a second card is retried on the emptier side with the smallest bend that clears', () => {
  // Cards stacked above the corridor need a bend beyond the cap; below, one extra card (E) blocks the first small
  // detours but a ~210 bend clears everything. Today only the straight line's blocker (A) produces candidates.
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 0), card('B', 300, -64), card('C', 300, -128),
    card('D', 300, -200), card('E', 300, 64)], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.deepEqual(obstructedCards(graph, bends), [], `bend ${bends.get('s-t')}`);
  assert.ok(Math.abs(bends.get('s-t')) <= 600 * 0.75, `bend ${bends.get('s-t')} exceeds 0.75 × length`);
  const curve = curveOf(graph, bends, 's-t');
  assert.ok(curve.control.y > 0, `the clear side is below (control ${curve.control.y})`);
});

test('a corridor stacked on both sides is still cleared by a bend derived from the second blockers', () => {
  const stack = [];
  for (let i = 1; i <= 4; i++) stack.push(card(`up${i}`, 300, -64 * i), card(`down${i}`, 300, 64 * i));
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 0), ...stack], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.deepEqual(obstructedCards(graph, bends), [], `bend ${bends.get('s-t')}`);
  assert.ok(Math.abs(bends.get('s-t')) <= 600 * 1.25, `bend ${bends.get('s-t')} exceeds the cap`);
});

test('an arrow that only grazes the margin of a card stays straight when the only clear route is a wide arc', () => {
  // A's top edge is 5 px below the line (inside the 9 px margin, outside the card); any clearing detour must also pass
  // B above or C below, i.e. needs a bend of 200 px or more on a 600 px edge.
  const graph = { revision: 1, nodes: [card('s', 0, 0), card('t', 600, 0), card('A', 300, 28), card('B', 300, -40), card('C', 300, 110)], edges: [link('s', 't')] };
  const bends = optimizeEdgeBends(graph.nodes, graph.edges, 2);
  assert.equal(bends.get('s-t'), 0, `bend ${bends.get('s-t')}`);
  // Through the card body, the arc is still taken.
  const blocked = { ...graph, nodes: graph.nodes.map((node) => (node.id === 'A' ? { ...node, y: 10 } : node)) };
  assert.notEqual(optimizeEdgeBends(blocked.nodes, blocked.edges, 2).get('s-t'), 0);
});

// The user's stored Square layout (Values off): four columns, three rows, card centres from the live page.
const STORED_GRID = { Alice: [956.19, 295.95], Bob: [476.19, 295.95], Carol: [796.19, 295.95], Acme: [796.19, 377.95], Dave: [956.19, 377.95],
  Oslo: [636.19, 295.95], Widget: [636.19, 459.95], Gadget: [476.19, 459.95], Gizmo: [636.19, 377.95], Norway: [476.19, 377.95] };

test('an arrow that no single bend can clear follows the gaps between the cards of a grid', () => {
  const graph = badExportGraph((name, kind) => (kind === 'literal' ? { x: 0, y: 0 } : { x: 0, y: 0 }));
  graph.nodes = graph.nodes.map((node) => (STORED_GRID[node.label] && node.kind === 'iri' ? { ...node, x: STORED_GRID[node.label][0], y: STORED_GRID[node.label][1] } : node));
  const drawn = canvasGraph(graph, false);
  const { bends, routes } = routeDrawnGraph(graph, false, 3);
  assert.ok(routes.size > 0, 'some arrow needs a stepped route');
  const byId = new Map(drawn.nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(drawn.nodes, drawn.edges);
  const minX = Math.min(...drawn.nodes.map((n) => n.x)) - 56 - 120, maxX = Math.max(...drawn.nodes.map((n) => n.x)) + 56 + 120;
  const minY = Math.min(...drawn.nodes.map((n) => n.y)) - 23 - 120, maxY = Math.max(...drawn.nodes.map((n) => n.y)) + 23 + 120;
  for (const edge of drawn.edges) {
    const curve = edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edge.id) ?? 0,
      ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target)), routes.get(edge.id));
    for (const p of curveSamples(curve, 400)) {
      assert.ok(p.x >= minX && p.x <= maxX && p.y >= minY && p.y <= maxY, `${edge.id} leaves the grid at ${Math.round(p.x)},${Math.round(p.y)}`);
      for (const node of drawn.nodes) {
        if (node.id === edge.source || node.id === edge.target) continue;
        const size = graphNodeSize(node);
        assert.ok(Math.abs(p.x - node.x) >= size.width / 2 || Math.abs(p.y - node.y) >= size.height / 2, `${edge.id} crosses ${node.label}`);
      }
    }
  }
});

test('a stepped route is drawn only while both cards are where it was computed for', () => {
  const a = card('a', 0, 0), b = card('b', 400, 200);
  const route = { source: { x: 0, y: 0 }, target: { x: 400, y: 200 }, points: [{ x: 57.5, y: 0 }, { x: 200, y: 0 }, { x: 200, y: 200 }, { x: 342.5, y: 200 }] };
  const routed = edgeGeometry(a, b, 0, undefined, undefined, route);
  assert.deepEqual(routed.points, route.points);
  assert.equal(routed.start.x, 57.5);
  assert.ok(!routed.path.includes(' Q ') || routed.path.split(' Q ').length === 3, 'two rounded corners');
  const moved = edgeGeometry({ ...a, x: 30 }, b, 0, undefined, undefined, route);
  assert.equal(moved.points, undefined, 'a card moved: the stale route is ignored');
});

test('hit testing, the middle and the WebGL lines follow a stepped route', () => {
  // Right along the top, down, a short way right: the straight line from a to b runs well away from most of it.
  const route = { source: { x: 0, y: 0 }, target: { x: 400, y: 200 }, points: [{ x: 57.5, y: 0 }, { x: 300, y: 0 }, { x: 300, y: 200 }, { x: 342.5, y: 200 }] };
  const curve = edgeGeometry(card('a', 0, 0), card('b', 400, 200), 0, undefined, undefined, route);
  const curves = new Map([['a-b', curve]]);
  assert.equal(nearestEdge({ x: 296, y: 60 }, curves, 7), 'a-b', 'the vertical leg');
  assert.equal(nearestEdge({ x: 100, y: 50 }, curves, 7), null, 'the straight line between the cards is not the arrow');
  const middle = curveMidpoint(curve);
  assert.ok(Math.abs(middle.x - 300) < 1 && Math.abs(middle.y) < 12, `middle ${JSON.stringify(middle)}`);
  const vertices = createGraphVertexCache()({ nodes: [card('a', 0, 0), card('b', 400, 200)], edges: [link('a', 'b')], revision: 1 }, curves);
  const points = [];
  for (let i = 0; i < vertices.lines.length; i += 2) points.push({ x: vertices.lines[i], y: vertices.lines[i + 1] });
  const segments = [];
  for (let i = 0; i < points.length; i += 2) segments.push([points[i], points[i + 1]]);
  assert.ok(segments.some(([a, b]) => Math.abs(a.x - 300) < 0.5 && Math.abs(b.x - 300) < 0.5 && Math.abs(a.y - b.y) > 150), 'the vertical leg is drawn');
  assert.ok(!points.some((p) => Math.abs(p.y - p.x / 2) < 2 && p.x > 120 && p.x < 280), 'no straight line is drawn');
});

// The export that showed the bug: three arrows from Alice to Bob left Alice in order but swapped order at Bob and
// crossed there, bunched against Bob's corner. Alice also has three incoming arrows from blank nodes.
const parallelScene = (aliceId, bobId) => {
  const alice = { id: aliceId, label: 'Alice', kind: 'iri', x: 727.2, y: 362.7 };
  const bob = { id: bobId, label: 'Bob', kind: 'iri', x: 842.1, y: 240.5 };
  const blanks = [[489.7, 412.7], [956.2, 436.5], [721.6, 506]].map(([x, y], i) => ({ id: `_:b${i}`, label: 'Blank node', kind: 'blank', x, y }));
  const between = (source, target, predicate) => ({ id: `${source.id}|${predicate}|${target.id}`, source: source.id, target: target.id, predicate, label: predicate });
  return { alice, bob, nodes: [alice, bob, ...blanks], blankEdges: blanks.map((blank) => between(blank, alice, 'about')), between };
};

function parallelCurves(nodes, edges) {
  const byId = new Map(nodes.map((node) => [node.id, node]));
  const ports = computeEdgePorts(nodes, edges), bends = optimizeEdgeBends(nodes, edges, 2);
  return edges.map((edge) => edgeGeometry(byId.get(edge.source), byId.get(edge.target), bends.get(edge.id) ?? 0,
    ports.get(edgePortKey(edge.id, edge.source)), ports.get(edgePortKey(edge.id, edge.target))));
}

function crossingPairs(curves) {
  const sampled = curves.map((curve) => Array.from({ length: 41 }, (_, i) => quadraticPoint(curve.start, curve.control, curve.end, i / 40)));
  const pairs = [];
  for (let a = 0; a < sampled.length; a++) {
    for (let b = a + 1; b < sampled.length; b++) {
      let touches = false;
      for (let i = 0; i < 40 && !touches; i++) {
        for (let j = 0; j < 40 && !touches; j++) touches = segmentDistance(sampled[a][i], sampled[a][i + 1], sampled[b][j], sampled[b][j + 1]) < 0.8;
      }
      if (touches) pairs.push([a, b]);
    }
  }
  return pairs;
}

test('parallel arrows between two cards keep their order at both cards', () => {
  // Both id orders: the lanes bend along the normal from the smaller id to the larger, whichever card that is.
  for (const [aliceId, bobId] of [['urn:alice', 'urn:bob'], ['urn:zoe', 'urn:bob']]) {
    const { alice, bob, nodes, blankEdges, between } = parallelScene(aliceId, bobId);
    for (const parallel of [
      ['knows', 'follows', 'worksWith'].map((predicate) => between(alice, bob, predicate)),
      [between(alice, bob, 'knows'), between(bob, alice, 'follows'), between(alice, bob, 'worksWith')],
    ]) {
      const curves = parallelCurves(nodes, [...blankEdges, ...parallel]).slice(blankEdges.length);
      assert.deepEqual(crossingPairs(curves), [], `${aliceId}/${bobId} ${parallel.map((edge) => edge.id).join(', ')}: ${curves.map((curve) => curve.path).join(' | ')}`);
    }
  }
  // A card between them: the middle arrow detours to one side, and the lane on that side must go round it, not cross it.
  const nodes = [card('a', 0, 0), card('z', 0, 1000), card('blocker', 0, 500)];
  const edges = ['one', 'three'].map((id) => ({ ...link('a', 'z'), id })).concat({ ...link('z', 'a'), id: 'two' });
  const curves = parallelCurves(nodes, edges);
  assert.deepEqual(crossingPairs(curves), [], curves.map((curve) => curve.path).join(' | '));
});

test('a card linked to only one neighbour centres its ports on that neighbour', () => {
  assert.deepEqual(distributeCircularPortParameters([40, 40, 40], 300).map((parameter) => Math.round(parameter * 1000) / 1000), [28, 40, 52]);
  const { alice, bob, nodes, blankEdges, between } = parallelScene('urn:alice', 'urn:bob');
  const parallel = ['knows', 'follows', 'worksWith'].map((predicate) => between(alice, bob, predicate));
  const ports = computeEdgePorts(nodes, [...blankEdges, ...parallel]);
  const atBob = parallel.map((edge) => ports.get(edgePortKey(edge.id, bob.id)));
  const ideal = nodeBoundaryPoint(bob, alice);
  const mean = { x: atBob.reduce((sum, port) => sum + port.x, 0) / 3, y: atBob.reduce((sum, port) => sum + port.y, 0) / 3 };
  assert.ok(Math.hypot(mean.x - ideal.x, mean.y - ideal.y) < 1, `ports ${JSON.stringify(atBob)} centre ${JSON.stringify(mean)}, ideal ${JSON.stringify(ideal)}`);
});
